//! Hashing, Ed25519 and the byte formats of the AIRSAFE ledger protocol (see docs/PROTOCOL.md).
//! Every format here is cross-checked against backend/fixtures/web3_vectors.json, generated by an independent
//! JavaScript implementation (tools/lib/web3ref.mjs).
use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine};
use ed25519_dalek::{Signature, Signer, SigningKey, Verifier, VerifyingKey};
use sha2::{Digest, Sha256};

pub fn sha256(data: &[u8]) -> [u8; 32] {
    Sha256::digest(data).into()
}

pub fn sha256_hex(data: &[u8]) -> String {
    hex::encode(sha256(data))
}

pub fn b64u(data: &[u8]) -> String {
    URL_SAFE_NO_PAD.encode(data)
}

pub fn b64u_decode(s: &str) -> Option<Vec<u8>> {
    URL_SAFE_NO_PAD.decode(s.trim()).ok()
}

/// Constant-time equality for secrets and digests.
pub fn ct_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

/// A fresh device API key: 32 random bytes, base64url. Only its SHA-256 is stored.
pub fn generate_api_key() -> String {
    b64u(&rand::random::<[u8; 32]>())
}

/// Bytes a device signs: `AIRSAFE-READING-V1\n{device_id}\n{exact request body}`.
pub fn reading_sig_message(device_id: &str, body: &[u8]) -> Vec<u8> {
    let mut m = format!("AIRSAFE-READING-V1\n{device_id}\n").into_bytes();
    m.extend_from_slice(body);
    m
}

/// Ledger leaf input: commits to the device, the reading time, the exact body and the device signature.
pub fn leaf_input(device_id: &str, reading_ms: i64, body: &[u8], signature: Option<&str>) -> Vec<u8> {
    format!(
        "AIRSAFE-LEAF-V1|{}|{}|{}|{}",
        device_id,
        reading_ms,
        sha256_hex(body),
        signature.unwrap_or("-")
    )
    .into_bytes()
}

pub fn checkpoint_message(batch_id: i64, root_hex: &str, leaf_count: i64, from_ms: i64, to_ms: i64) -> Vec<u8> {
    format!("AIRSAFE-CHECKPOINT-V1|{batch_id}|{root_hex}|{leaf_count}|{from_ms}|{to_ms}").into_bytes()
}

pub fn verify_ed25519(public: &[u8; 32], msg: &[u8], sig: &[u8]) -> bool {
    let vk = match VerifyingKey::from_bytes(public) {
        Ok(v) => v,
        Err(_) => return false,
    };
    let sig_bytes = match <[u8; 64]>::try_from(sig) {
        Ok(b) => b,
        Err(_) => return false,
    };
    let signature = Signature::from_bytes(&sig_bytes);
    vk.verify(msg, &signature).is_ok()
}

pub fn sign_ed25519(key: &SigningKey, msg: &[u8]) -> Vec<u8> {
    key.sign(msg).to_bytes().to_vec()
}

pub fn public_key_of(key: &SigningKey) -> [u8; 32] {
    key.verifying_key().to_bytes()
}

/// `did:key` identifier of an Ed25519 public key (multicodec 0xed01, base58btc, 'z' prefix).
pub fn did_key(public: &[u8; 32]) -> String {
    let mut bytes = vec![0xed_u8, 0x01];
    bytes.extend_from_slice(public);
    format!("did:key:z{}", bs58::encode(bytes).into_string())
}

/// Accepts a raw 32-byte hex key or a `did:key:z6Mk...` identifier.
pub fn parse_public_key(input: &str) -> Result<[u8; 32], String> {
    let s = input.trim();
    if let Some(rest) = s.strip_prefix("did:key:z") {
        let bytes = bs58::decode(rest).into_vec().map_err(|e| format!("invalid did:key: {e}"))?;
        if bytes.len() == 34 && bytes[0] == 0xed && bytes[1] == 0x01 {
            return <[u8; 32]>::try_from(&bytes[2..]).map_err(|_| "invalid did:key length".to_string());
        }
        return Err("did:key is not an Ed25519 key".to_string());
    }
    let bytes = hex::decode(s.trim_start_matches("0x")).map_err(|_| "public key must be hex or did:key".to_string())?;
    <[u8; 32]>::try_from(bytes.as_slice()).map_err(|_| "public key must be 32 bytes".to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ct_eq_behaves() {
        assert!(ct_eq(b"abc", b"abc"));
        assert!(!ct_eq(b"abc", b"abd"));
        assert!(!ct_eq(b"abc", b"ab"));
    }

    #[test]
    fn did_key_round_trips() {
        let key = SigningKey::from_bytes(&[5u8; 32]);
        let public = public_key_of(&key);
        let did = did_key(&public);
        assert!(did.starts_with("did:key:z6Mk"));
        assert_eq!(parse_public_key(&did).unwrap(), public);
        assert_eq!(parse_public_key(&hex::encode(public)).unwrap(), public);
        assert!(parse_public_key("zz").is_err());
    }

    #[test]
    fn ed25519_sign_verify() {
        let key = SigningKey::from_bytes(&[1u8; 32]);
        let public = public_key_of(&key);
        let sig = sign_ed25519(&key, b"hello");
        assert!(verify_ed25519(&public, b"hello", &sig));
        assert!(!verify_ed25519(&public, b"hellO", &sig));
        assert!(!verify_ed25519(&public, b"hello", &sig[..10]));
    }
}
